command:
apk add --no-cache git bash build-base curl >/dev/null 2>&1 || true; mkdir -p /app/bin; cd /app; if [ -n "$GIT_REPOSITORY_URL" ]; then AUTH_REPO_URL="$GIT_REPOSITORY_URL"; if [ -n "$GITHUB_TOKEN" ]; then AUTH_REPO_URL=$(echo "$GIT_REPOSITORY_URL" | sed -E "s#https://#https://${GITHUB_TOKEN}@#"); fi; if [ ! -d .git ]; then echo '[Runner] Clonando repositório Go...'; git clone --branch "$GIT_BRANCH" "$AUTH_REPO_URL" . ; else echo '[Runner] Atualizando repositório Go...'; git remote set-url origin "$AUTH_REPO_URL"; git fetch origin "$GIT_BRANCH"; git checkout "$GIT_BRANCH"; git pull origin "$GIT_BRANCH"; fi; else if [ ! -f main.go ] && [ ! -f go.mod ]; then echo '[Runner] Criando aplicação Go demo...'; cat << 'EOF' > main.go
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"os"
)

func main() {
	port := os.Getenv("APP_PORT")
	if port == "" {
		port = "8080"
	}
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{
			"status":  "online",
			"runtime": "Golang 1.24",
			"message": "ServApp Go ativo no Cosmos-Server",
		})
	})
	fmt.Printf("Servidor Go ouvindo na porta %s\n", port)
	http.ListenAndServe(":"+port, nil)
}
EOF
fi; fi; if [ -f go.mod ] && [ -n "$INSTALL_CMD" ]; then echo "[Runner] Executando: $INSTALL_CMD"; eval "$INSTALL_CMD"; fi; if [ -n "$BUILD_CMD" ]; then echo "[Runner] Executando: $BUILD_CMD"; eval "$BUILD_CMD"; fi; echo "[Runner] Iniciando binário: $START_CMD"; if [ -f /app/bin/server ]; then exec /app/bin/server; elif [ -f main.go ]; then exec go run main.go; else exec /bin/sh -c "$START_CMD"; fi
